package fr.cake.client;
import net.minecraft.client.Minecraft;import net.minecraft.world.entity.*;import net.minecraft.world.phys.Vec3;import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;import com.mojang.blaze3d.vertex.PoseStack;import java.util.*;
public final class CombatEffects{
 public static final String[] NAMES={"Ascension","Soul Rift","Crystal Shatter","Supernova","Cyber Fade"};
 private record Pending(int hurt,long time){}private record Death(Vec3 at,long time,int style,int color,int seed){}private static final Map<Integer,Pending> pending=new HashMap<>();private static final Map<Integer,Long> hits=new HashMap<>();private static final WeakHashMap<Object,Integer> states=new WeakHashMap<>();private static final ArrayDeque<Death> deaths=new ArrayDeque<>();private static final Set<Integer> dead=new HashSet<>();private static Object world;
 public static void attack(Entity e){if(e instanceof LivingEntity l&&pending.size()<12)pending.put(e.getId(),new Pending(l.hurtTime,System.nanoTime()));}
 public static void capture(LivingEntity e,LivingEntityRenderState state){states.put(state,e.getId());}
 public static void tick(Minecraft mc){if(world!=mc.level){pending.clear();hits.clear();deaths.clear();dead.clear();states.clear();world=mc.level;}if(mc.level==null||mc.player==null||mc.isPaused())return;long now=System.nanoTime();pending.entrySet().removeIf(e->{var entity=mc.level.getEntity(e.getKey());if(entity instanceof LivingEntity l&&l.hurtTime>e.getValue().hurt){hits.put(e.getKey(),now);return true;}return now-e.getValue().time>900_000_000L;});hits.entrySet().removeIf(e->now-e.getValue()>650_000_000L);var s=CakeClient.settings;
 if(s.deathEffects){for(var e:mc.level.entitiesForRendering()){if(!(e instanceof LivingEntity l)||e==mc.player||e.isInvisible()||e.distanceToSqr(mc.player)>1024)continue;if(l.deathTime>0&&dead.add(e.getId())){int color=java.awt.Color.HSBtoRGB((float)s.hitColorHue,.6f,1)&0xffffff;deaths.add(new Death(e.position().add(0,.2,0),now,s.deathStyle,color,e.getId()));while(deaths.size()>4)deaths.removeFirst();}if(l.deathTime==0)dead.remove(e.getId());}if(dead.size()>256)dead.clear();}else deaths.clear();deaths.removeIf(d->now-d.time>2_200_000_000L);
 }
 public static boolean tinted(Object state){Integer id=states.get(state);return CakeClient.settings.hitColor&&id!=null&&hits.containsKey(id);}
 public static int tint(Object state,int argb){Integer id=states.get(state);if(id==null||!tinted(state))return argb;float t=(float)Math.max(0,1-(System.nanoTime()-hits.get(id))/650_000_000.);float strength=(float)CakeClient.settings.hitColorStrength*t;int rgb=java.awt.Color.HSBtoRGB((float)CakeClient.settings.hitColorHue,.8f,1);int a=argb>>>24;if(a==0)a=255;int out=a<<24;for(int shift:new int[]{16,8,0})out|=(int)(((argb>>shift)&255)*(1-strength)+((rgb>>shift)&255)*strength)<<shift;return out;}
 public static void pose(Object state,PoseStack stack){if(!CakeClient.settings.deathEffects||!(state instanceof LivingEntityRenderState s)||s.deathTime<=0)return;float p=Math.clamp(s.deathTime/20f,0,1);switch(CakeClient.settings.deathStyle){case 0-> {stack.translate(0,-p*.7,0);stack.mulPose(new org.joml.Quaternionf().rotationY(p*2));}case 1->{stack.translate(0,-p*.2,0);stack.scale(1-p*.65f,1+p*.4f,1-p*.65f);}case 2->stack.mulPose(new org.joml.Quaternionf().rotationY(p*4));case 3->{float k=1+(float)Math.sin(p*Math.PI)*.3f;stack.scale(k,k,k);}case 4->stack.scale(1,Math.max(.02f,1-p),1);}}
 public static void render(){long now=System.nanoTime();for(var d:deaths){double age=(now-d.time)/1e9,p=age/2.2,fade=Math.pow(Math.max(0,1-p),1.4),radius=.35+1.8*p;int cell=switch(d.style){case 1->9;case 2->14;case 3->13;case 4->11;default->8;};SpriteBatch.floor(d.at,radius,(float)(age*.3),d.color,(float)fade,cell);SpriteBatch.floor(d.at.add(0,.01,0),radius*.68,(float)-age,d.color,(float)(fade*.6),12);
 for(int i=0;i<26;i++){double a=i*2.399963+d.seed*.13;double r=(.15+(i%7)*.06)*(1+2*p),height=age*(.5+(i%5)*.15);if(d.style==2)r*=2;if(d.style==3){r=age*(.5+i%5*.16);height=Math.sin(i*2.1)*r+.7;}var at=d.at.add(Math.cos(a+age)*r,height,Math.sin(a+age)*r);SpriteBatch.add(at,.035+.065*fade,(float)(a+age),d.color,(float)fade,SpriteBatch.cell(d.style==2?20:0));if(i%3==0)SpriteBatch.ribbon(at.add(0,-.3*fade,0),at,.022,d.color,0,(float)fade,SpriteBatch.cell(7));}
 }}
}
